{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Lefamulin, a complex diterpenoid antibiotic, has an absolute oral bioavailability of 21.08% in humans when comparing a 600 mg oral tablet to IV infusion, directly supporting F ≥ 20% for a structurally related polycyclic diterpenoid lactone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "BMS-275183, a taxane diterpenoid with a complex polycyclic ester/lactone scaffold, has an oral bioavailability of ~24% in humans, supporting high bioavailability for the query's similar complex polycyclic lactone architecture.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tacrolimus, a macrocyclic lactone immunosuppressant, shows absolute oral bioavailability of 25.0% in pediatric liver transplant recipients, with other studies reporting values around 20–25%, supporting F ≥ 20% for a complex lipophilic lactone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Digitoxin, a steroid-like polycyclic lactone, has an absolute oral bioavailability of 90.6% in healthy subjects, demonstrating that complex lipophilic lactone scaffolds can achieve high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Amphotericin B has negligible oral bioavailability in humans, but this is attributed to a large polyene macrolide with poor permeability, low solubility, and instability at gastric pH, features not present in the query molecule.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most transferable experimental evidence from structurally related complex diterpenoid and macrocyclic lactones (lefamulin ~21–26%, BMS-275183 ~24%, tacrolimus ~20–25%) supports F ≥ 20%. The main contradictory evidence, amphotericin B's negligible oral bioavailability, is mechanistically tied to a polyene macrolide with ionizable and polyhydroxylated features absent in the query. Therefore, high bioavailability is better supported, though the threshold is borderline.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data exist for the query molecule itself.",
    "Closest analogues cluster near the 20% threshold, so the prediction is sensitive to small differences in permeability and first-pass metabolism.",
    "Amphotericin B's low-F evidence has a high transfer score but is mechanistically less applicable to the query's non-polyene, non-ionizable scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

